"Верно. Их места рождения отмечены на карте Казахстана.": "Тоғра. Уларниң туғулған җайлири Қазақстан хәритисидә бәлгүләнгән.",
"Верно. Значок показывает место рождения Коркыта.": "Тоғра. Бәлгү Қорқутниң туғулған җайини көрситиду.",
"Неверно. «Отан» написал композитор К. Сакай, а Роза Рымбаева исполняет «Землю мою».": "Хата. «Отан» нахшисини композитор К. Сакай язған, «Меним зиминим» нахшисини болса Роза Римбаева орундайду.",
"Верно. Это яркий пример эстрадного вокала.": "Тоғра. Бу эстрада вокалиниң ярқин мисали.",
"Неверно. Композитор «Земли моей» — П. Ермишев.": "Хата. «Меним зиминим» нахшисиниң композитори — П. Ермишев.",
"Верно. М. Суворов — автор слов.": "Тоғра. М. Суворов — сөз автори.",
"Верно. Это песня о Родине.": "Тоғра. Бу Вәтән һәққидики нахша.",
"Неверно. Слова написал Е. Баятулы.": "Хата. Сөзини Е. Баятулы язған.",
"Верно. Можно рассказать, где слушал музыку и чем она запомнилась.": "Тоғра. Музикини қәйәрдә аңлиғанлиқни вә у немиси билән есидә қалғанлиқни сөзләп беришкә болиду.",
"Неверно. Она показывает места, связанные с музыкой и музыкантами.": "Хата. У музика вә музыкантлар билән бағлиқ җайларни көрситиду.",
"Найди: «Земля моя»": "Тап: «Меним зиминим»",
"Найди: «Отан»": "Тап: «Отан»",
