"Урок 2. Музыкальный путеводитель": "2-дәрис. Музикилиқ йол көрсәткүч",
"Музыкальный путеводитель": "Музикилиқ йол көрсәткүч",
"Объяснять, что такое музыкальный путеводитель и аккомпанемент, называть композиторов урока и характеризовать классический вокал.": "Музикилиқ йол көрсәткүч вә аккомпанемент немә екәнлигини чүшәндүрүш, дәристики композиторларни аташ вә классикилиқ вокални тәсвирләш.",
"Аккомпанемент": "Аккомпанемент",
"Аккомпанемент сопровождает мелодию. Так и музыка сопровождает нас во всех путешествиях. По-казахски это сүйемелдеу, по-английски accompaniment.": "Аккомпанемент муңни йөләп туриду. Музикиму шундақла бизни һәммә сәпәрләрдә йөләп жүриду. Қазақчә бу сүйемелдеу, инглизчә accompaniment.",
"Путеводитель": "Йол көрсәткүч",
"Это справочник для путешественников. Вся информация в нём собрана по принципу: кто? что? где?": "Бу сәяһәтчиләр үчүн мәлумат китави. Униңдики барлиқ мәлумат мундақ принцип бойичә топланған: ким? немә? қәйәрдә?",
"Чтобы его составить, нужно подобрать интересные примеры музыкальной культуры Казахстана и указать, где можно узнать о них подробнее.": "Уни түзүш үчүн Қазақстанниң музикилиқ мәдәнийитиниң қизиқарлиқ мисалларни таллап, улар һәққидә тәпсилий қәйәрдин билишкә болидиғанлиқини көрситиш керәк.",
"Композиторы урока": "Дәристики композиторлар",
"Владимир Шаинский (1925–2017) — детский композитор. Ахмет Жубанов (1906–1968) — казахский композитор, основатель оркестра казахских народных инструментов (ОКНИ). Франц Йозеф Гайдн (1732–1809) — австрийский композитор.": "Владимир Шаинский (1925–2017) — балилар композитори. Әхмәт Жубанов (1906–1968) — қазақ композитори, қазақ хәлқ қураллири оркестриниң (ҚХҚО) асасчиси. Франц Йозеф Гайдн (1732–1809) — австрийәлик композитор.",
"Глинка и классический вокал": "Глинка вә классикилиқ вокал",
"Михаил Иванович Глинка (1804–1857) — русский композитор, автор оперы «Руслан и Людмила», симфонической фантазии «Камаринская» и «Вальса-фантазии». «Попутная песня» Глинки — яркий пример классического вокала: голоса певцов этой школы отличаются силой. Классический вокал — традиционный способ пения, который встречается в опере, оперетте и академическом хоре.": "Михаил Иванович Глинка (1804–1857) — рус композитори, «Руслан вә Людмила» операсиниң, «Камаринская» симфониялик фантазиясиниң вә «Вальс-фантазияниң» автори. Глинкиниң «Йолдики нахша» әсири — классикилиқ вокалниң ярқин мисали: бу мәктәптики нахшичиларниң авази күчи билән пәрқлиниду. Классикилиқ вокал — нахша ейтишниң әнәнивий усули, у опера, оперетта вә академиялик хорда учрайду.",
