"Урок 3. Красота родной земли — источник вдохновения": "3-дәрис. Она җутниң гөзәллиги — илһам мәнбәси",
"Красота родной земли — источник вдохновения": "Она җутниң гөзәллиги — илһам мәнбәси",
"Объяснять, как природа родного края вдохновляет композиторов, и различать вокал и вокализ.": "Туғулған өлкиниң тәбиити композиторларға қандақ илһам беридиғанлиғини чүшәндүрүш вә вокал билән вокализни пәриқләндүрүш.",
"Природа и музыка": "Тәбиәт вә музика",
"Природа Казахстана очень разная. Красота родного края вдохновляла композиторов создавать свои произведения.": "Қазақстанниң тәбиити наһайити хилму-хил. Туғулған өлкиниң гөзәллиги композиторларни өз әсәрлирини яритишқа илһамландурған.",
"Родной пейзаж": "Она җутниң мәнзириси",
"Где бы ни жил человек — у величественного Илейского Алатау или в бескрайней степи Сарыарки, — пейзаж родного края для него самый красивый.": "Адәм қәйәрдә яшимисун — һәйвәтлик Или Алатавиниң йенида яки Сарыарқаниң чәксиз далисида, — туғулған өлкиниң мәнзириси униң үчүн әң гөзәл.",
"Кюй «Алатау»": "«Алатау» күйи",
"Кюй «Алатау» написал композитор Курмангазы Сагырбайулы. Слушая его, можно подобрать слова, которые описывают характер музыки.": "«Алатау» күйини композитор Қурманғазы Сағырбайұлы яратқан. Уни аңлап, музикиниң характерини тәсвирләйдиған сөзләрни талливелишқа болиду.",
"Вокал и вокализ": "Вокал вә вокализ",
"Вокал — это пение. Вокализ — когда мелодию исполняют голосом без слов, без текста.": "Вокал — нахша ейтиш. Вокализ — муңни сөзсиз, текстсиз авазда орундаш.",
"Джузеппе Верди": "Джузеппе Верди",
"Джузеппе Верди (1813–1901) — итальянский композитор. Его творчество — одно из крупнейших достижений мирового оперного искусства. Он написал оперу «Набукко» («Навуходоносор»).": "Джузеппе Верди (1813–1901) — итальянлиқ композитор. Униң ижадийити дуняви опера сәнитиниң әң чоң утуқлиридин бири. У «Набукко» («Навуходоносор») операсини язған.",
"Разложи: вокал или вокализ": "Бөл: вокал яки вокализ",
"Прочитай карточку и реши, о чём она: о вокале или о вокализе.": "Карточкини оқуп, у немә һәққидә екәнлигини — вокал яки вокализ екәнлигини бәлгүлә.",
