"Верно. Так сказано про эти горы.": "Тоғра. Бу тағлар һәққидә шундақ дейилгән.",
"Верно. Оно — достижение мирового оперного искусства.": "Тоғра. У дуняви опера сәнитиниң утуқи.",
"Неверно. Он жил в 1813–1901 годах, то есть в XIX веке.": "Хата. У 1813–1901-жиллири, йәни XIX әсирдә яшиған.",
"Найди: Вокал": "Тап: Вокал",
"Найди: Вокализ": "Тап: Вокализ",
"Найди: Джузеппе Верди": "Тап: Джузеппе Верди",
"Найди: Курмангазы Сагырбайулы": "Тап: Қурманғазы Сағырбайұлы",
"Найди: Природа родного края": "Тап: Она җутниң тәбиити",
"Урок 4. С чего начинается Родина?": "4-дәрис. Вәтән нәдин башлиниду?",
"С чего начинается Родина?": "Вәтән нәдин башлиниду?",
"Объяснять, что такое народный вокал, и называть длительности нот и пауз.": "Хәлқ вокали немә екәнлигини чүшәндүрүш вә нота вә пауза узунлуқлирини аташ.",
"Родина начинается с дома": "Вәтән өйдин башлиниду",
"Казахская поговорка говорит, что дорога начинается с порога родного дома. Родина — это дом, близкие, праздники и песни, которые мы берегём в сердце.": "Қазақ мақалида йол туғулған өйниң бусуғисидин башлиниду дейилиду. Вәтән — өй, йеқинлар, байрамлар вә биз көңлимиздә сақлайдиған нахшилар.",
"Колыбельная": "Бешик нахшиси",
"Самая первая песня, которую мы слышим, — песня мамы. Во всех странах колыбельная — символ материнской любви, заботы и ласки.": "Биз аңлайдиған әң тунҗи нахша — аниниң нахшиси. Барлиқ әлләрдә бешик нахшиси — ана муһәббитиниң, ғәмхорлуқниң вә меһри-шәпқитиниң символи.",
"Ласточка — символ дома": "Қарлиғач — өйниң символи",
"Многие народы считают ласточку символом родного дома. Поэтому песни о ласточке напоминают нам о Родине.": "Нурғун хәлқләр қарлиғачни туғулған өйниң символи дәп һесаплайду. Шуңа қарлиғач һәққидики нахшилар бизгә Вәтәнни есимизгә салиду.",
"Народный вокал": "Хәлқ вокали",
"Это вид пения, в основе которого лежат вокальные традиции конкретного народа. Часто народные исполнители поют в особой «разговорной» манере, горловым «плоским» звуком.": "Бу нахша ейтишниң бир түри, униң асасида муәййән хәлқниң вокал әнәнилири ята. Хәлқ орунучилири көпинчә алаһидә «сөзләшкән» услубта, бөғуздин чиққан «яссиқ» аваз билән ейтиду.",
"Ноты, паузы и длительности": "Нотилар, паузилар вә узунлуқлар",
"Есть целая, половинная, четвертная и восьмая ноты. Пауза — это тишина в музыке, и равные по длительности ноты и паузы называются одинаково.": "Пүтүн, йерим, чарәк вә сәккизинчи нотилар бар. Пауза — музикидики җимҗитлиқ, узунлуғи тәң нотилар билән паузилар охшаш атилиду.",
"Разложи по длительности": "Узунлуғи бойичә бөл",
"Определи, к какой длительности относится каждая карточка.": "Һәр бир карточка қайси узунлуққа мунасивәтлик екәнлигини ениқла.",
