"Верно. Ласточка — символ дома.": "Тоғра. Қарлиғач — өйниң символи.",
"Неверно. Он основан на вокальных традициях конкретного народа.": "Хата. У муәййән хәлқниң вокал әнәнилиригә асасланған.",
"Верно. Это особенность народного вокала.": "Тоғра. Бу хәлқ вокалиниң алаһидилиги.",
"Верно. Она исполнила песню «Ласточка».": "Тоғра. У «Қарлиғач» нахшисини орундиди.",
"Неверно. Пауза — это тишина.": "Хата. Пауза — җимҗитлиқ.",
"Верно. Например, целая нота и целая пауза.": "Тоғра. Мәсилән, пүтүн нота вә пүтүн пауза.",
"Неверно. Целая нота длиннее четвертной.": "Хата. Пүтүн нота чарәктин узун.",
"Верно. Е. Крылатов — композитор этой песни.": "Тоғра. Е. Крилатов — бу нахшиниң композитори.",
