"Урок 5. Ты — Человек!": "5-дәрис. Сән — Адәм!",
"Ты — Человек!": "Сән — Адәм!",
"Называть вечные человеческие ценности и рассказывать о сиртаки, композиторе Микисе Теодоракисе и песне «Ты — Человек».": "Мәңгүлүк инсаний қиммәтләрни атап, сиртаки, композитор Микис Теодоракис һәққидә вә «Сән — Адәм» нахшиси һәққидә сөзләш.",
"Человеческие ценности": "Инсаний қиммәтләр",
"Любовь, добро, мир, Родина, семья, природа, красота и дружба — вечные человеческие ценности. Ими дорожит каждый человек.": "Муһәббәт, яхшилиқ, тинчлиқ, Вәтән, аилә, тәбиәт, гөзәллик вә достлуқ — мәңгүлүк инсаний қиммәтләр. Уларни һәр бир адәм әзиз көриду.",
"О чём говорит музыка": "Музика немә һәққидә сөзләйду",
"Многие музыкальные произведения рассказывают об этих ценностях. Музыка передаёт мысли и переживания человека и рисует картины природы.": "Көплигән музикилиқ әсәрләр бу қиммәтләр һәққидә сөзләйду. Музика адәмниң ой-пикирлирини вә һиссиятлирини йәткүзиду һәм тәбиәт мәнзирилирини сизиду.",
"Микис Теодоракис": "Микис Теодоракис",
"Это греческий композитор и дирижёр. Он написал много симфоний, камерных произведений, а также популярных песен и танцев в народном стиле.": "Бу грек композитори вә дирижёри. У көплигән симфонийә, камера әсәрлири, шундақла хәлиқ усулидики мәшһур нахша вә уссуллар йезип чиққан.",
"Сиртаки": "Сиртаки",
"Это самый популярный греческий танец в мире и один из символов Греции. Его принято считать народным, но на самом деле музыку придумал Микис Теодоракис.": "Бу дунйадики әң мәшһур грек уссули вә Грецийәниң рәмзлиридин бири. Уни хәлиқ уссули дәп һесаплайду, әмма әмәлийәттә музикини Микис Теодоракис ойлап чиққан.",
"Песня «Ты — Человек»": "«Сән — Адәм» нахшиси",
"Песня из кинофильма «Приключения Электроника». Музыку написал Е. Крылатов, слова — Ю. Энтин. В песне есть куплеты и припев.": "«Электрониқниң саяһәтлири» кинофильмидики нахша. Музикисини Е. Крылатов, сөзлирини Ю. Энтин йезип чиққан. Нахшида бәнтләр вә нақарат бар.",
"Разложи по произведениям": "Әсәрләр бойичә бөл",
"Барсик просит помочь: определи, к какому произведению относится каждая карточка.": "Барсик ярдәм сорайду: һәр бир карточка қайси әсәргә мунасивәтлик екәнлигини ениқла.",
"К какому произведению относится?": "Қайси әсәргә мунасивәтлик?",
