"Куплеты и припев — части этой песни.": "Бәнтләр вә нақарат — бу нахшиниң қисимлири.",
"Верно. Любовь, добро, мир, семья, природа, красота и дружба — вечные ценности.": "Тоғра. Муһәббәт, яхшилиқ, тинчлиқ, аилә, тәбиәт, гөзәллик вә достлуқ — мәңгүлүк қиммәтләр.",
