"Песня и человек": "Нахша вә адәм",
"С песней мы радуемся и грустим. Песня — верный спутник человека в радости и в печали.": "Нахша билән биз шатлинимиз вә ғәм қилимиз. Нахша — шатлиқта вә ғәмдә адәмниң садиқ һәмраһи.",
