"Весёлые, задорные, шуточные и лиричные песни звучат на детских праздниках, в походах, во время отдыха и работы.": "Хуш-хуй, җүрәклик, һәзилий вә лирикилиқ нахшилар балилар байрамлирида, сәпәрләрдә, дәм елиш вә ишләш вақтида аңлиниду.",
"Чему учат песни": "Нахшилар немигә үгитиду",
"Авторы часто описывали в песнях достоинства и недостатки, поступки людей. Так песня помогает стать лучше и добрее.": "Авторлар нахшиларда көп вақитта адәмләрниң яхши вә яман тәрәплирини, қилмишлирини тәсвирләйду. Шундақ қилип нахша яхши вә меһрибан болушқа ярдәм бериду.",
"Бахытжан Байкадамов": "Бахытжан Байқадамов",
"Казахский композитор (1917–1977), основоположник хорового пения в Казахстане, первый аранжировщик кюев и народных песен.": "Қазақ композитори (1917–1977), Қазақстанда хор нахша ейтишниң асасчиси, кюйләр вә хәлиқ нахшилириниң тунҗи аранжировщиги.",
"Исаак Дунаевский": "Исаак Дунаевский",
