"С песней мы можем и радоваться, и грустить.": "Нахша билән биз һәм шатлиналаймиз, һәм ғәм қиламиз.",
"Песни звучат только на концертах.": "Нахшилар пәқәт концертларда аңлиниду.",
"Авторы песен иногда описывали поступки людей, чтобы помочь им стать лучше.": "Нахша авторлири бәзидә адәмләрниң яхши болушиға ярдәм бериш үчүн қилмишлирини тәсвирлигән.",
"Бахытжан Байкадамов — советский дирижёр.": "Бахытжан Байқадамов — совет дирижёри.",
"Байкадамов был первым аранжировщиком кюев и народных песен.": "Байқадамов кюйләр вә хәлиқ нахшилириниң тунҗи аранжировщиги болди.",
"Исаак Дунаевский — автор музыки к кинофильмам.": "Исаак Дунаевский — кинофильмларға музика автори.",
"Увертюра Дунаевского написана к фильму «Беспокойная весна».": "Дунаевскийниң увертюриси «Тинчсиз яз» фильмиға йезилған.",
"Песня «Девушка-водовоз» написана для фильма «Беспокойная весна».": "«Су ташидиған қиз» нахшиси «Тинчсиз яз» фильми үчүн йезилған.",
"Народ называл Байкадамова «казахским Дунаевским».": "Хәлиқ Байқадамовни «қазақ Дунаевский» дәп атиған.",
"Домбры, сделанные по расчётам Байкадамова, считаются худшими в республике.": "Байқадамовниң һесаплири бойичә ясалған домбралар республикида әң яманлар һесаплиниду.",
"Песня — верный спутник человека.": "Нахша — адәмниң садиқ һәмраһи.",
"Они звучат на праздниках, в походах, во время отдыха и работы.": "Улар байрамларда, сәпәрләрдә, дәм елиш вә иш вақтида аңлиниду.",
"Он казахский композитор.": "У қазақ композитори.",
"Он советский композитор и дирижёр.": "У совет композитори вә дирижёри.",
"Она написана к фильму «Дети капитана Гранта».": "У «Капитан Грантниң балилири» фильмиға йезилған.",
"Её композитор — Бахытжан Байкадамов.": "Униң композитори — Бахытжан Байқадамов.",
"Люди любили его песни и быстро подхватывали их.": "Адәмләр униң нахшилирини яхши көрәтти вә тез әгишип ейтатти.",
"Наоборот, они и сегодня считаются лучшими.": "Әксичә, улар бүгүнму әң яхшилар һесаплиниду.",
"Верно. Песня — верный спутник человека.": "Тоғра. Нахша — адәмниң садиқ һәмраһи.",
"Неверно. Они звучат на праздниках, в походах, во время отдыха и работы.": "Хата. Улар байрамларда, сәпәрләрдә, дәм елиш вә иш вақтида аңлиниду.",
"Верно. Песня может учить добру.": "Тоғра. Нахша яхшилиққа үгитиши мумкин.",
"Неверно. Он казахский композитор.": "Хата. У қазақ композитори.",
"Верно. Он обрабатывал кюи и народные песни.": "Тоғра. У кюйләр вә хәлиқ нахшилирини ишлигән.",
"Верно. Он советский композитор и дирижёр.": "Тоғра. У совет композитори вә дирижёри.",
"Неверно. Она написана к фильму «Дети капитана Гранта».": "Хата. У «Капитан Грантниң балилири» фильмиға йезилған.",
"Верно. Её композитор — Бахытжан Байкадамов.": "Тоғра. Униң композитори — Бахытжан Байқадамов.",
"Верно. Люди любили его песни и быстро подхватывали их.": "Тоғра. Адәмләр униң нахшилирини яхши көрәтти вә тез әгишип ейтатти.",
"Неверно. Наоборот, они и сегодня считаются лучшими.": "Хата. Әксичә, улар бүгүнму әң яхшилар һесаплиниду.",
