"Урок 7. От сердца к сердцу": "7-дәрис. Жүрәктин жүрәккә",
"От сердца к сердцу": "Жүрәктин жүрәккә",
"Различать виды певческих голосов и называть ансамбли по числу исполнителей.": "Нахша ейтиш авазлириниң түрлирини пәриқләндүрүш вә ансамбльләрни орундиғучилар сани бойичә аташ.",
"Голоса по высоте": "Егизлиги бойичә аваз",
"Певческие голоса бывают высокие, средние и низкие. Слушатель может больше любить низкие, средние или высокие голоса.": "Нахша ейтиш авазлири егиз, оттура вә пәс болиду. Аңлиғучи пәс, оттура яки егиз авазларни көпрәк яхши көрүши мумкин.",
"Детские голоса": "Балилар авазлири",
"У детей бывают дискант (высокий голос) и альт (средний голос).": "Балиларда дискант (егиз аваз) вә альт (оттура аваз) болиду.",
"Женские и мужские голоса": "Аяллар вә әрләр авазлири",
"Женские голоса: сопрано, меццо-сопрано, контральто. Мужские: тенор, баритон, бас.": "Аяллар авазлири: сопрано, меццо-сопрано, контральто. Әрләр авазлири: тенор, баритон, бас.",
"Ансамбль": "Ансамбль",
"Слово «ансамбль» по-французски значит «вместе». Это когда несколько человек вместе играют, поют или танцуют. Двое исполнителей — дуэт.": "«Ансамбль» сөзи французчә «биллә» дегән мәнани бериду. Бу бир нәччә адәмниң биллә челиши, нахша ейтиши яки уссул ойниши. Икки орундиғучи — дуэт.",
"Состав ансамбля": "Ансамбль тәркиви",
"Трио — три музыканта, квартет — четыре, квинтет — пять, секстет — шесть, септет — семь, октет — восемь, нонет — девять. Большой коллектив — оркестр, ансамбль певцов — хор. Ими руководит дирижёр.": "Трио — үч музыкант, квартет — төт, квинтет — бәш, секстет — алтә, септет — йәттә, октет — сәккиз, нонет — тоққуз. Чоң топ — оркестр, нахшичилар ансамбли — хор. Уларға дирижёр башчилиқ қилиду.",
"Разложи голоса": "Авазларни бөл",
"Определи, кому принадлежит каждый певческий голос.": "Һәр бир нахша ейтиш авази кимгә тәвә екәнлигини ениқла.",
