"Объяснять, что такое рондо, и различать в нём рефрен и эпизоды.": "Рондоның немә екәнлигини чүшәндүрүш вә униңда рефрен билән эпизодларни пәриқләндүрүш.",
"Рондо": "Рондо",
"Рондо — это музыкальная форма. В ней неизменная тема чередуется с разными эпизодами.": "Рондо — музикилиқ шәкил. Униңда өзгәрмәс тема түрлүк эпизодлар билән алмишип келиду.",
"Рефрен": "Рефрен",
"Рефрен — это основная мелодия. Она возвращается в рондо снова и снова.": "Рефрен — бу асасий мелодийә. У рондода қайта-қайта қайтип келиду.",
"Эпизод": "Эпизод",
"Эпизод — это дополнительная мелодия. Эпизоды между возвращениями рефрена разные.": "Эпизод — бу қошумчә мелодийә. Рефренниң қайтип келишлири арисидики эпизодлар түрлүк болиду.",
"Цепочка событий": "Вақиәләр зәнҗири",
"Сказка А.С. Пушкина «О рыбаке и рыбке» тоже как цепочка: повторяется встреча старика с золотой рыбкой, а между встречами происходят разные события.": "А.С. Пушкинниң «Балиқчи вә балиқ һәққидә» әпсаниси худдии зәнҗир: бовай билән алтун балиқниң учрашқини тәкрарлиниду, учрашқанлар арисида түрлүк вақиәләр йүз бериду.",
"Рондо и наша жизнь": "Рондо вә бизниң һаятимиз",
"Мы часто возвращаемся к одному и тому же: идём на учёбу или прогулку и с радостью возвращаемся домой. Рондо запоминает такую закономерность в музыке.": "Биз көп вақитта бир нәрсигә қайтип келимиз: оқушқа яки сәйлигә баримиз вә хушал болуп өйгә қайтимиз. Рондо музикида мундақ қанунийәтни ядта тутиду.",
