"Еліміздің мемлекеттік рәміздері — Ту, Елтанба және Қазақстан Республикасының Мемлекеттік Гимні.": "Елимизниң дөләт рәмизлири — Туғ, Герб вә Қазақстан Республикисиниң Дөләт Гимни.",
"Гимн деген не?": "Гимн дегән немә?",
"Гимн — мемлекеттік рәміздердің бірі. Бұл — музыкалық шығарма, ол салтанатты мерекелік іс-шараларда орындалады.": "Гимн — дөләт рәмизлиридин бири. Бу — музикилиқ әсәр, у шәрәплик байрам тәдбирлиридә орунлиниду.",
"Гимннің авторлары": "Гимнниң авторлири",
"Гимннің әнін Ш. Қалдаяқов жазған, ал өлеңін Ж. Нәжімеденов пен Н. Назарбаев жазған. Гимнді тік тұрып, оң қолды жүрекке қойып тыңдаймыз.": "Гимнниң нахшисини Ш. Қалдаяқов йезип, шеирини Ж. Нәжімеденов билән Н. Назарбаев йезип чиққан. Гимнни турип, оң қолни жүрәккә қойуп аңлаймиз.",
"«Дарқан дала» әні": "«Дарқан дала» нахшиси",
"«Дарқан дала» әнінің өлеңін С. Мәуленов, әнін С. Еркімбеков жазған. Ән оркестр, хор немесе солист түрінде орындалуы мүмкін. Балалар ақыны Абдрахман Асылбектің «Қазақстан — елім менің!» өлеңі де Отанға деген сүйіспеншілікті білдіреді.": "«Дарқан дала» нахшисиниң шеирини С. Мәуленов, нахшисини С. Еркімбеков йезип чиққан. Нахша оркестр, хор яки солист шәклидә орунлиниши мүмкин. Балилар ақини Абдрахман Асылбекниң «Қазақстан — елим мениң!» шеири Вәтәнгә болған муһәббәтни ипадилийду.",
"Кім жазды?": "Ким йезип чиққан?",
"Әр карточканы дұрыс шығармаға қой: Мемлекеттік Гимн немесе «Дарқан дала».": "Һәр бир карточкини тоғра әсәргә қой: Дөләт Гимни яки «Дарқан дала».",
