"2-сабақ. Нұр-Сұлтан — Қазақстанның астанасы": "2-дәрис. Нур-Сұлтан — Қазақстанниң пайтәхти",
"Нұр-Сұлтан — Қазақстанның астанасы": "Нур-Сұлтан — Қазақстанниң пайтәхти",
"Астана туралы әндер мен күйді ажыратып, канон түрінде орындау дегеннің не екенін түсіндіру.": "Пайтәхт һәққидики нахша вә күйләрни айрип, канон шәклидә орунлаш дегәнниң немә екәнлигини чүшәндүрүш.",
"Астана — елдің жүрегі": "Астана — елниң жүриги",
"Нұр-Сұлтан — Қазақстанның астанасы. Жыл санап өсіп, көркейіп келеді, оған арналған өлеңдер мен әндер көп.": "Нур-Сұлтан — Қазақстанниң пайтәхти. Жил сайин өсүп, гөзәлләшмәктә, униңға беғишланған шеир вә нахшилар көп.",
"Үлкен ел": "Чоң ел",
"Қазақстан жерінің көлемі жағынан дүниежүзінде тоғызыншы орын алады. Табиғаты сұлу, халқы тату.": "Қазақстан зимининиң көлими җәһәттин дунядә тоққузинчи орунни егиләйду. Тәбиити гөзәл, хәлқи иттипақ.",
"«Арман қала — астана»": "«Арман қала — астана»",
"Бұл — астанаға арналған ән. Өлеңін де, әнін де М. Омаров жазған. Әннің мазмұны — қаланың көркі мен қуанышы.": "Бу — пайтәхткә беғишланған нахша. Шеирини дә, нахшисини дә М. Омаров йезип чиққан. Нахшиниң мәзмуни — шәһәрниң гөзәллиги вә шатлиғи.",
"«Шабыт» күйі": "«Шабыт» күйи",
"«Шабыт» — Т. Тоқжановтың күйі. Күйді тыңдап, оның көңіл күйін, қандай сезім сыйлайтынын айтамыз.": "«Шабыт» — Т. Тоқжановниң күйи. Күйни аңлап, униң кәйпиятини, қандақ һес бәргәнлигини ейтимиз.",
"Канон дегеніміз не?": "Канон дегән немә?",
"Канон түрінде орындау — әннің негізгі әуенін сақтап, оны топтардың бірінен кейін бірінің қайталап айтуы. Мұны «Дарқан дала» әнінің қайырмасымен үйренеміз.": "Канон шәклидә орунлаш — нахшиниң асаслиқ авазини сақлап, уни группиларниң бири-биридин кейин тәкрарлап ейтиши. Буни «Дарқан дала» нахшисиниң нақарати билән үгинимиз.",
