"Астанаға тарту": "Астанаға соға",
"«Астанам» әнін талдап, «Астанаға тарту» ойынының шартын түсіндіру және сөзжұмбақ тапсырмасын атау.": "«Астанам» нахшисини талла қилип, «Астанаға соға» оюниниң шәртини чүшәндүрүш вә кроссворд тапшурмисини аташ.",
"«Астанам» әні": "«Астанам» нахшиси",
"«Астанам» — елордаға арналған ән. Оның сөзі мен әнін А. Адиханова жазған.": "«Астанам» — пайтәхткә беғишланған нахша. Униң сөзи билән нахшисини А. Адиханова йезип чиққан.",
"Әннің қайырмасы — қайталанып айтылатын басты бөлігі. Қайырма әннің негізгі көңіл күйін жеткізеді.": "Нахшиниң нақарати — тәкрарлинип ейтилидиған асаслиқ қисми. Нақарат нахшиниң асаслиқ кәйпиятини йәткүзиду.",
"«Астанамызға тарту» ойыны": "«Астанимизға соға» оюни",
"Сынып үш топқа бөлінеді: «Суретшілер», «Әншілер», «Бишілер». Әр топ астанаға арнайы сыйлық дайындайды.": "Синип үч группиға бөлүниду: «Рәссамлар», «Нахшичилар», «Уссулчилар». Һәр бир группа астанаға алаһидә соға тәйярлайду.",
"Топтардың сыйлығы": "Группиларниң согиси",
"Суретшілер сурет салады, әншілер бір әнді орындайды, бишілер би билейді. Содан кейін әр топ таныстырылым жасап, түсінік береді.": "Рәссамлар рәсим сизиду, нахшичилар бир нахшини орунлайду, уссулчилар уссул ойнайду. Андин һәр бир группа тәқдимат қилип, чүшәнчә бериду.",
"«Астанам — ән қала» сөзжұмбағы": "«Астанам — нахша шәһири» кроссворди",
"Сөзжұмбақта қала аттары, «Астанам» сөзі, музыкалық терминдер мен аспап атаулары болады. Олар «ән қала» деген сөздерді құрастырады.": "Кроссвордта шәһәр намлири, «Астанам» сөзи, музикилиқ терминлар вә чалғу намлири болиду. Улар «нахша шәһири» дегән сөзләрни түзиду.",
