"Онда қала аттары, терминдер мен аспап атаулары болады.": "Униңда шәһәр намлири, терминлар вә чалғу намлири болиду.",
"Онда қала аттары, музыкалық терминдер және аспап атаулары болады.": "Униңда шәһәр намлири, музикилиқ терминлар вә чалғу намлири болиду.",
"Дұрыс. Ән еліміздің бас қаласына арналған.": "Тоғра. Нахша елимизниң баш шәһиригә беғишланған.",
"Дұрыс. Сөзі де, әні де бір авторға тиесілі.": "Тоғра. Сөзи дә, нахшисиму бир авторға тәвә.",
"Бұрыс. Қайырма әнде қайталанып айтылады.": "Хата. Нақарат нахшида тәкрарлинип ейтилиду.",
"Дұрыс. Суретшілер, әншілер және бишілер.": "Тоғра. Рәссамлар, нахшичилар вә уссулчилар.",
"Бұрыс. Сурет салатын — суретшілер тобы; бишілер би билейді.": "Хата. Рәсим сизидиғини — рәссамлар групписи; уссулчилар уссул ойнайду.",
