"Туған өлкемді жырлаймын": "Туғулған елимни күйләймән",
"Туған жер туралы әндерді айту, «ән», «гимн», «канон», «репетиция» ұғымдарын түсіндіру және топта жұмыс істеу.": "Туғулған йәр һәққидики нахшиларни ейтиш, «нахша», «гимн», «канон», «репетиция» чүшәнчилирини чүшәндүрүш вә группида ишләш.",
"Туған өлке": "Туғулған өлкә",
"Әр адамның өз туған жері, туған өлкесі бар. Адам қайда жүрсе де, туған жері оған қымбат әрі ыстық.": "Һәр бир адәмниң өз туғулған йери, туғулған өлкиси бар. Адәм қәйәрдә жүрсиму, туғулған йери униңға қиммәтлик вә иссиқ.",
