"Бұл әнді 1-сыныпта үйрендіңдер. Өлеңін Б. Ысқақов жазған, әнін Ө. Байділдаев шығарған.": "Бу нахшини 1-синипта үгәндиңлар. Шеирини Б. Ысқақов йезип, нахшисини Ө. Байділдаев ижад қилған.",
