"Репетиция": "Репетиция",
"Репетиция – латын тілінде «қайталау» деген сөз. Дұрыс нәтижеге жету үшін шығарманы бірнеше рет қайталап орындайды.": "Репетиция – латин тилида «тәкрарлаш» дегән сөз. Тоғра нәтиҗигә йетиш үчүн әсәрни бирнәччә қетим тәкрарлап орунлайду.",
"Канон және гимн": "Канон вә гимн",
"Канон – негізгі әуенді бірнеше әнші кезек-кезек қайталап орындауы. Гимн – салтанатты ән, мемлекеттің рәміздерінің бірі; оны тұрып тыңдайды.": "Канон – асаслиқ авазни бирнәччә нахшичиниң нөвәт билән тәкрарлап орунлиши. Гимн – шәрәплик нахша, дөләт рәмизлиридин бири; уни турип аңлайду.",
