"Түсіндіру: құндылық дегеніміз не, басты құндылықтар қандай, және «Көк тудың желбірегені» әні туралы айту.": "Чүшәндүрүш: қиммәтлик дегән немә, асасий қиммәтликләр қандақ, вә «Көк туғниң желбирегени» нахшиси һәққидә сөзләш.",
"Құндылық дегеніміз не?": "Қиммәтлик дегән немә?",
"Құндылық – бұл бір нәрсенің мәнділігі, маңыздылығы, қалаулылығы, қымбаттылығы. Адамға тән махаббат, сүйіспеншілік, мейірімділік сезімдері құндылық деп аталады.": "Қиммәтлик – бу бирәр нәрсиниң мәнилик, муһим, арзулуқ, қиммәт болушидур. Адәмгә хас муһәббәт, сөйгү, меһрибанлиқ һес-туйғулири қиммәтлик дәп атилиду.",
"Басты құндылықтар": "Асасий қиммәтликләр",
"Басты құндылықтар – Отан, отбасы, ана тілі, рәміздер. Әрбір ана үшін баласы қымбат, әрбір адам үшін Отаны қымбат.": "Асасий қиммәтликләр – Вәтән, аилә, она тили, рәмизләр. Һәр бир ана үчүн балиси қиммәт, һәр бир адәм үчүн Вәтини қиммәт.",
"«Әйел-Ана» ертегісі": "«Аял-Ана» чөчиги",
"Бұл – жазушы А. Сейдімбектің ертегісі. Күншуақ елі қиын сәтте Әйел-Ананың ақылымен аман қалады.": "Бу – язғучи А. Сейдимбекниң чөчиги. Күншуақ ели қийин пәйттә Аял-Ананиң әқли билән аман қалиду.",
"«Көк тудың желбірегені»": "«Көк туғниң желбирегени»",
"Бұл – Отанға, көк туға деген құрметті жырлайтын ән. Өлеңін А. Ахметбекұлы жазған, әнін Е. Зейітхан шығарған.": "Бу – Вәтәнгә, көк туғға болған һөрмәтни күйләйдиған нахша. Шеирини А. Ахметбекұлы йезип чиққан, нахшисини Е. Зейітхан яратқан.",
"Әннің құрылысы": "Нахшиниң түзүлүши",
"Әнде екі шумақ пен қайырма бар. Әннің кіріспесін екі топқа бөлініп, екі дауыспен орындауға болады.": "Нахшида икки бәнт билән нақарат бар. Нахшиниң кириш қисмини икки топқа бөлүнүп, икки аваз билән орунлашқа болиду.",
