"Өлеңін И. Иса жазған, ал әнін (музыкасын) А. Бексұлтан шығарған. Өлең авторы сөзін, композитор әуенін жазады.": "Шеирини И. Иса йезип чиққан, нахшисини (музикисини) А. Бексұлтан яратқан. Шеир авторы сөзини, композитор аһаңни йезиду.",
"Шумақ пен қайырма": "Бәнт билән нақарат",
"Әннің бірнеше шумағы және қайырмасы бар. Шумақтардың сөзі өзгереді, ал қайырма әр шумақтан кейін қайталанып айтылады.": "Нахшида бир нәччә бәнт вә нақарат бар. Бәнтләрниң сөзи өзгириду, нақарат болса һәр бәнттин кейин тәкрарлинип ейтилиду.",
"Құндылықтар": "Қиммәтликләр",
"Әнде құрмет, алғыс, қамқорлық, мейірім сияқты жақсы қасиеттер айтылады. Бұл қасиеттер отбасын берік етеді.": "Нахшида һөрмәт, рәхмәт, ғәмхорлуқ, меһир охшаш яхши сүпәтләр ейтилиду. Бу сүпәтләр аилини мустәһкәм қилиду.",
"«Жасырынбақ» ойыны": "«Йошурунмақ» ойуни",
"Бұл суырыпсалма ойын. Екі топқа бөлініп, өсиет өлеңдердегі жасырылған сөздерді табады. Өлеңдер үлкенге құрмет, кішіге ізет туралы.": "Бу тосатин ойун. Икки топқа бөлүнүп, вәсийәт шеирлардики йошурулған сөзләрни тапиду. Шеирлар чоңларға һөрмәт, кичикләргә иззәт һәққидә.",
