"Бұрыс. Ән ата-әже мен әке-анаға деген құрмет туралы.": "Хата. Нахша чоң ата-чоң ана билән ата-анигә болған һөрмәт һәққидә.",
"Дұрыс. Құрмет — маңызды құндылық.": "Тоғра. Һөрмәт — муһим қиммәтлик.",
"Бұрыс. Үлкен кісіні сыйлап, сөзін бөлмей тыңдаймыз.": "Хата. Чоң кишини һөрмәтләп, сөзини бөлмәй аңлаймиз.",
"Дұрыс. Ойында екі топ жасырылған сөздерді табады.": "Тоғра. Ойунда икки топ йошурулған сөзләрни тапиду.",
