"Табыңыз: Үлкенге құрмет көрсету": "Тап: Чоңларға һөрмәт көрситиш",
"Табыңыз: Үлкенге құрметсіздік": "Тап: Чоңларға һөрмәтсизлик",
"Табыңыз: Талдау": "Тап: Таһлил",
"Табыңыз: Ән айту": "Тап: Нахша ейтиш",
"Табыңыз: Ойын және шығармашылық": "Тап: Ойун вә ижадийәт",
"7-сабақ. Достығымыз жарасқан": "7-дәрис. Достлуғимиз ярашқан",
"Достығымыз жарасқан": "Достлуғимиз ярашқан",
"«Жан досым» және «Достар әні» әндерінің авторларын атау, достықтың құндылықтарын түсіндіру және әннің орындалу ерекшеліктерін сипаттау.": "«Җан достум» вә «Достлар нахшиси» нахшилириниң авторлирини аташ, достлуқниң қиммәтликлирини чүшәндүрүш вә нахшиниң орунлаш алаһидиликлирини тәсвирләш.",
"«Жан досым» әні": "«Җан достум» нахшиси",
"Бұл әннің өлеңін Т. Молдағалиев жазған, әнін (музыкасын) композитор С. Бәйтереков шығарған. Ән жақын досқа арналған.": "Бу нахшиниң шеирини Т. Молдағалиев йезип чиққан, нахшисини (музикисини) композитор С. Бәйтереков яратқан. Нахша жиқин достқа беғишланған.",
"«Достар әні»": "«Достлар нахшиси»",
"Бұл әннің өлеңін А. Рахметов жазған, әнін Н. Мирманов шығарған. Ән достық, бірге болу туралы.": "Бу нахшиниң шеирини А. Рахметов йезип чиққан, нахшисини Н. Мирманов яратқан. Нахша достлуқ, биллә болуш һәққидә.",
"Неліктен «Жан досым»?": "Немә үчүн «Җан достум»?",
"«Жан дос» дегеніміз – ең жақын, сенімді дос. Ән осындай досқа арналғандықтан, солай аталған.": "«Җан дост» дегән – әң жиқин, ишәнчлик дост. Нахша шундақ достқа беғишлиғанлиқи үчүн шундақ атилған.",
"Достықтың құндылықтары": "Достлуқниң қиммәтликлири",
"Нағыз дос адал, қамқор, сенімді болады. Бір-біріне көмектесу, сыйлау және сырласу – достықты нығайтады.": "Һәқиқий дост адил, ғәмхор, ишәнчлик болиду. Бир-биригә ярдәмлишиш, һөрмәтләш вә сирдишиш – достлуқни мустәһкәмләйду.",
"Әннің орындалу ерекшелігі": "Нахшиниң орунлиниш алаһидилиги",
"Ән баяу немесе жылдам айтылуы мүмкін – бұл оның екпіні. Көңіл күйі лирикалы, ойнақы немесе жігерлі болады. Кейбір ән биге, кейбірі маршқа жақын ырғақпен орындалады.": "Нахша астиму яки тез ейтилиши мүмкин – бу униң екпини. Кәйпияти лирикилиқ, ойнақи яки җасарәтлик болиду. Бәзи нахшилар уссулға, бәзилири маршқа жиқин ритм билән орунлиниду.",
