"8-сабақ. Құндылықтар шеңбері": "8-дәрис. Қиммәтликләр чәмбири",
"Құндылықтар шеңбері": "Қиммәтликләр чәмбири",
"Құндылықтар деген не екенін түсіндіру, Н. Мирмановтың «Достар» және С. Бәйтерековтің «Көк тудың желбірегені» әндерін атау, f және p таңбаларын ажырату.": "Қиммәтликләрниң немә екәнлигини чүшәндүрүш, Н. Мирмановниң «Достлар» вә С. Бәйтерековниң «Көк туғниң желбирегени» нахшилирини аташ, f вә p бәлгүлирини айриш.",
"Құндылықтар деген не?": "Қиммәтликләр дегән немә?",
"Құндылықтар – адам үшін ең қымбат нәрселер: Отан-Ана, Жер, ұлт, ана тілі, отбасы, достық. Мейірімділік, адалдық, қайырымдылық та – жақсы қасиеттер.": "Қиммәтликләр – адәм үчүн әң қиммәтлик нәрсиләр: Вәтән-Ана, Йәр, милләт, она тили, аилә, достлуқ. Меһрибанлиқ, адиллиқ, яхшилиқ – шуларму яхши сүпәтләр.",
"Шаңырақ пен уықтар": "Шаңирақ вә уқлар",
"Сабақта құндылықтар шаңырақ пен уықтар арқылы көрсетілген. Шаңырақ – киіз үйдің төбесі, ал уықтар – оны ұстап тұратын таяқтар. Әр уықта бір құндылық тұр.": "Дәристә қиммәтликләр шаңирақ вә уқлар арқилиқ көрситилгән. Шаңирақ – кийиз өйниң төписи, уқлар болса уни тутуп туридиған таяқлар. Һәр бир уқта бир қиммәтлик туриду.",
"Ту, Гимн және Елтаңба – мемлекеттік рәміздер. Олар да біздің ортақ құндылықтарымыз қатарына жатады.": "Туғ, Гимн вә Герб – дөләт рәмизлири. Улар бизниң ортақ қиммәтликлиримизниң қатариға кириду.",
"Достық туралы ән": "Достлуқ һәққидики нахша",
"Н. Мирмановтың «Достар» әні достықты жырлайды. Достық – адамның ең сенімді серігі болу дегенді білдіреді.": "Н. Мирмановниң «Достлар» нахшиси достлуқни күйләйду. Достлуқ – адәмниң әң ишәнчлик һәмраһи болуш дегән мәна.",
"Динамикалық таңбалар": "Динамикилиқ бәлгүләр",
"f (форте) – әнді қатты орындау, p (пиано) – жай орындау. Бұл таңбалар музыканың қаншалықты қатты немесе жай шығатынын көрсетеді.": "f (форте) – нахшини қаттиқ орунлаш, p (пиано) – аста орунлаш. Бу бәлгүләр музикиниң қанчилик қаттиқ яки аста чиқидиғанлиғини көрситиду.",
"Құндылықтар мен қасиеттерді ретте": "Қиммәтликләр билән сүпәтләрни тәртипкә селиш",
